/** @param {NS} ns */
export async function main(ns) {
  const visited = new Set();
  const queue = ['home'];
  const depth_map = { 'home': 0 };
  const max_depth = 3;

  // Log hacking level
  const hack_level = ns.getHackingLevel();
  ns.tprint(`\n=== NETWORK DIAGNOSTIC ===`);
  ns.tprint(`Our Hacking Level: ${hack_level}`);

  // Check for port-openers
  const port_openers = [
    'BruteSSH.exe',
    'FTPCrack.exe',
    'relaySMTP.exe',
    'HTTPWorm.exe',
    'SQLInject.exe'
  ];
  const available_openers = [];
  for (const opener of port_openers) {
    if (ns.fileExists(opener, 'home')) {
      available_openers.push(opener);
    }
  }
  ns.tprint(`Port-openers available: ${available_openers.join(', ') || 'none'}`);
  ns.tprint(`\n=== DISCOVERED SERVERS ===\n`);

  // BFS
  while (queue.length > 0) {
    const current = queue.shift();

    if (visited.has(current)) continue;
    visited.add(current);

    const current_depth = depth_map[current];

    // Get server info
    const max_money = ns.getServerMaxMoney(current);
    const min_sec = ns.getServerMinSecurityLevel(current);
    const req_hack = ns.getServerRequiredHackingLevel(current);
    const ports_req = ns.getServerNumPortsRequired(current);
    const max_ram = ns.getServerMaxRam(current);
    const has_root = ns.hasRootAccess(current);

    // Print server info
    ns.tprint(`${current}:`);
    ns.tprint(`  maxMoney: $${(max_money / 1e6).toFixed(3)}m`);
    ns.tprint(`  minSec: ${min_sec}`);
    ns.tprint(`  reqHackLvl: ${req_hack}`);
    ns.tprint(`  portsReq: ${ports_req}`);
    ns.tprint(`  maxRam: ${max_ram}GB`);
    ns.tprint(`  hasRoot: ${has_root}`);
    ns.tprint('');

    // Scan neighbors if we haven't reached max depth
    if (current_depth < max_depth) {
      const neighbors = ns.scan(current);
      for (const neighbor of neighbors) {
        if (!visited.has(neighbor)) {
          depth_map[neighbor] = current_depth + 1;
          queue.push(neighbor);
        }
      }
    }
  }

  ns.tprint(`\n=== SCAN COMPLETE ===");
}

/** @param {NS} ns */
export async function main(ns) {
  const visited = new Set(['home']);
  const queue = [['home', 0]];
  const servers = [];

  // BFS depth 5
  while (queue.length > 0) {
    const [host, depth] = queue.shift();
    if (depth > 5) continue;

    const neighbors = ns.scan(host);
    for (const neighbor of neighbors) {
      if (!visited.has(neighbor)) {
        visited.add(neighbor);
        servers.push(neighbor);
        if (depth < 5) queue.push([neighbor, depth + 1]);
      }
    }
  }

  // Port openers
  const openers = [
    () => { if (ns.fileExists('BruteSSH.exe')) ns.brutessh(host); },
    () => { if (ns.fileExists('FTPCrack.exe')) ns.ftpcrack(host); },
    () => { if (ns.fileExists('relaySMTP.exe')) ns.relaysmtp(host); },
    () => { if (ns.fileExists('HTTPWorm.exe')) ns.httpworm(host); },
    () => { if (ns.fileExists('SQLInject.exe')) ns.sqlinject(host); }
  ];

  // Attempt nuke on each server
  const rooted = [];
  for (const host of servers) {
    try {
      const portsReq = ns.getServerNumPortsRequired(host);
      for (let i = 0; i < portsReq && i < openers.length; i++) {
        try { openers[i](); } catch (e) {}
      }
      ns.nuke(host);
      rooted.push(host);
    } catch (e) {}
  }

  // Rank targets
  const myHackLvl = ns.getHackingLevel();
  const targets = [];

  for (const host of rooted) {
    const maxMoney = ns.getServerMaxMoney(host);
    if (maxMoney <= 0) continue;
    const reqHack = ns.getServerRequiredHackingLevel(host);
    if (reqHack > myHackLvl) continue;
    const minSec = ns.getServerMinSecurityLevel(host);
    targets.push({
      host,
      maxMoney,
      minSec,
      reqHackLvl: reqHack,
      score: maxMoney / minSec
    });
  }

  targets.sort((a, b) => b.score - a.score);
  const top5 = targets.slice(0, 5);

  ns.tprint('TOP TARGETS:');
  for (const t of top5) {
    ns.tprint(`${t.host}: $${(t.maxMoney/1e6).toFixed(2)}m, minSec=${t.minSec}, reqHack=${t.reqHackLvl}`);
  }
  ns.tprint(`TARGETS=[${top5.map(t => `{host:${t.host},maxMoney:${t.maxMoney},minSec:${t.minSec}}`).join(',')}]`);
}

/** @param {NS} ns */
export async function main(ns) {
  const bfs = (start, maxDepth) => {
    const visited = new Set(), queue = [[start, 0]];
    const servers = [];
    while (queue.length > 0) {
      const [srv, d] = queue.shift();
      if (visited.has(srv) || d > maxDepth) continue;
      visited.add(srv);
      servers.push(srv);
      for (const neighbor of ns.scan(srv)) {
        if (!visited.has(neighbor)) queue.push([neighbor, d + 1]);
      }
    }
    return servers;
  };

  const openPort = (srv, opener, exe) => {
    try {
      if (ns.fileExists(exe)) opener(srv);
    } catch (e) {}
  };

  const rootServers = () => {
    const servers = bfs('home', 6);
    const rooted = [];
    for (const srv of servers) {
      if (!ns.hasRootAccess(srv)) {
        openPort(srv, ns.brutessh, 'BruteSSH.exe');
        openPort(srv, ns.ftpcrack, 'FTPCrack.exe');
        openPort(srv, ns.relaysmtp, 'relaySMTP.exe');
        openPort(srv, ns.httpworm, 'HTTPWorm.exe');
        openPort(srv, ns.sqlinject, 'SQLInject.exe');
        ns.nuke(srv);
      }
      if (ns.hasRootAccess(srv)) rooted.push(srv);
    }
    return rooted;
  };

  const pickTarget = (rooted, myLvl) => {
    let best = null, bestScore = -1;
    for (const srv of rooted) {
      const reqLvl = ns.getServerRequiredHackingLevel(srv);
      const maxMoney = ns.getServerMaxMoney(srv);
      const minSec = ns.getServerMinSecurityLevel(srv);
      if (reqLvl > myLvl / 2 || maxMoney === 0) continue;
      const score = maxMoney / (minSec + 1);
      if (score > bestScore) {
        bestScore = score;
        best = srv;
      }
    }
    return best || 'n00dles';
  };

  let myLvl = ns.getHackingLevel();
  let rooted = rootServers();
  let target = pickTarget(rooted, myLvl);
  ns.tprint(`Starting with target: ${target}`);

  let iterCount = 0;
  while (true) {
    const minSec = ns.getServerMinSecurityLevel(target);
    const maxMoney = ns.getServerMaxMoney(target);
    const curSec = ns.getServerSecurityLevel(target);
    const curMoney = ns.getServerMoneyAvailable(target);

    if (curSec > minSec + 5) {
      await ns.weaken(target);
    } else if (curMoney < maxMoney * 0.75) {
      await ns.grow(target);
    } else {
      await ns.hack(target);
    }

    iterCount++;
    if (iterCount % 20 === 0) {
      const newLvl = ns.getHackingLevel();
      if (newLvl > myLvl) {
        myLvl = newLvl;
        rooted = rootServers();
        const newTarget = pickTarget(rooted, myLvl);
        if (newTarget !== target) {
          target = newTarget;
        }
      }
    }
    if (iterCount % 50 === 0) {
      ns.tprint(`[${iterCount}] Target: ${target}, Sec: ${curSec.toFixed(2)}/${minSec}, Money: $${curMoney.toFixed(0)}/$${maxMoney.toFixed(0)}`);
    }
  }
}

/** @param {NS} ns */
export async function main(ns) {
  const allowed = new Set(['scan','nuke','brutessh','ftpcrack','hasRootAccess','getServerNumPortsRequired','getServerMaxMoney','getServerMinSecurityLevel','getServerSecurityLevel','getServerMoneyAvailable','getServerRequiredHackingLevel','getHackingLevel','hack','grow','weaken','fileExists','tprint']);

  function bfs(start, maxDepth) {
    const seen = new Set([start]);
    const queue = [[start, 0]];
    const servers = [];
    while (queue.length) {
      const [srv, d] = queue.shift();
      servers.push(srv);
      if (d < maxDepth) {
        for (const next of ns.scan(srv)) {
          if (!seen.has(next)) {
            seen.add(next);
            queue.push([next, d+1]);
          }
        }
      }
    }
    return servers;
  }

  function findTarget(srvs) {
    let best = 'n00dles', bestVal = -1;
    const myLvl = ns.getHackingLevel();
    for (const s of srvs) {
      if (!ns.hasRootAccess(s)) continue;
      const maxM = ns.getServerMaxMoney(s);
      if (maxM <= 0) continue;
      const reqLvl = ns.getServerRequiredHackingLevel(s);
      if (reqLvl > myLvl) continue;
      const minSec = ns.getServerMinSecurityLevel(s);
      const val = maxM / (minSec + 1);
      if (val > bestVal) { best = s; bestVal = val; }
    }
    return best;
  }

  function gainRoot(srvs) {
    for (const s of srvs) {
      if (ns.hasRootAccess(s)) continue;
      const ports = ns.getServerNumPortsRequired(s);
      try {
